  1688→                    if ((rect.width > 48 || rect.height > 48) && !['BUTTON','A','UL','LI','NAV','SPAN'].includes(tag)) {
  1689→                        el.style.display = 'none';
  1690→                    }
  1691→                    // Ensure buttons/links show text, not icons
  1692→                    if ((tag === 'A' || tag === 'BUTTON' || tag === 'SPAN') && el.querySelectorAll && el.querySelectorAll('svg,i,img').length) {
  1693→                        el.querySelectorAll('svg,i,img').forEach(x=>x.remove());
  1694→                        if (!el.textContent.trim()) {
  1695→                            // set sensible fallback
  1696→                            if (el.getAttribute('aria-label') && /previous/i.test(el.getAttribute('aria-label'))) el.textContent = '‹';
  1697→                            else if (el.getAttribute('aria-label') && /next/i.test(el.getAttribute('aria-label'))) el.textContent = '›';
  1698→                        }
  1699→                    }
  1700→                } catch (e) {
  1701→                    // ignore
  1702→                }
  1703→            });
  1704→        }
  1705→        clean();
  1706→        const mo = new MutationObserver(clean);
  1707→        mo.observe(root, { childList: true, subtree: true, attributes: true });
  1708→    });
  1709→}
